self.KB_CONTENT["card:778800"]={"id":"card:778800","ty":"card","sourceId":"778800","title":"『採購計劃鎖定作業』的作業目的為何","ver":"GP4以上","topic":"採購單","keywords":["採購單","計劃","發放","鎖定"],"y":"explain","answer":"可以將批次採購計劃的全部或一部分設定為鎖定，以免重新計劃時有所更動或局部發放採購單或請購單。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[778800,779635],"file":"kb-cards.jsonl"};
