self.KB_CONTENT["card:792260"]={"id":"card:792260","ty":"card","sourceId":"792260","title":"『保修報工單憑證列印』的作業目的為何？","ver":"GP4以上","topic":"憑證","keywords":["憑證","工單","存檔","保修"],"y":"explain","answer":"透過此作業可以將保修報工單建立作業(ASMI18)中設備保修的報工記錄列印出來，以作為資料檢核或存檔備查的依據。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
