self.KB_CONTENT["card:756192"]={"id":"card:756192","ty":"card","sourceId":"756192","title":"『暫出/入歸還建立作業』中的『確認碼 (TH020)』為何？","ver":"iGP","topic":"暫出入","keywords":["暫出入","作廢","失敗","歸還"],"y":"other","answer":"* 隱藏欄位。預設N。* 確認碼僅可接受 Y/N/U/V 之判斷值（Y.已確認、N.未確認、U.確認失敗、V.作廢）。派車資料","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
