self.KB_CONTENT["card:780779"]={"id":"card:780779","ty":"card","sourceId":"780779","title":"『資料匯出入欄位設定作業』中的『轉換值 (TG008)』為何？","ver":"GP4以上","topic":"出入","keywords":["出入"],"y":"other","answer":"* 若「轉換值欄位型態」為「N.Numeric」時，「轉換值」不可輸入文字，預設為「0」。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
