self.KB_CONTENT["card:782063"]={"id":"card:782063","ty":"card","sourceId":"782063","title":"『票據融資建立作業』中的『已兌現金額 (TH019)』為何？","ver":"GP4以上","topic":"單身","keywords":["單身","票據","融資","合計"],"y":"other","answer":"* 此欄位僅作顯示。* 單身全部票據其目前票況=「6.兌現」之金額合計。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
