self.KB_CONTENT["card:779133"]={"id":"card:779133","ty":"card","sourceId":"779133","title":"『暫出/入單建立作業(IDL)』中的『歸還贈/備品DIE量 (TG049)』為何？","ver":"GP4以上","topic":"暫出入","keywords":["暫出入","入單","歸還"],"y":"other","answer":"* 此欄位不可輸入，由暫出/入歸還單據更新此暫出/入單已歸還的贈/備品DIE量。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
