self.KB_CONTENT["field:753810"]={"id":"field:753810","ty":"field","sourceId":"753810","title":"備註","ver":"iGP","topic":"","keywords":[],"job":"稅別碼設定作業","code":"NN009","answer":"* 可點選 (icon)或[F2]片語資料查詢。* 可搭配基本參數設定的備註預設(1.公用片語 2.個人片語 N.不預設)使用，在備註欄位輸入片語代號按Enter後直接帶回片語內容。※ 加扣款設定作業","file":"fields.jsonl"};
